132	// The L3-REAL decoder megakernel needs the token path + a grad-partial workspace
133	// in addition to the FuseTier::{L1,L3} ABI. We keep it a SEPARATE kernel +
134	// launcher (not folded into fused_megakernel) so the surrogate path is untouched.
135	//
136	// Workspace layout (one flat float buffer the host allocates + the kernel owns):
137	//   [0 .. nCTA*total)              : per-CTA grad partials (cta-major)
138	//   [nCTA*total .. nCTA*total+nCTA): per-CTA loss partials (NLL sum per slice)
139	//   [.. +1)                        : the reduced scalar loss (loss/B) the host reads
140	// total == kDecTotalElems == 422755.
141	
142	struct DecoderTokenCtx {
143	    const int* tokens;   // [B, kSeq] int32 token ids in [0, kVocab)
144	    const int* targets;  // [B]       int32 target ids
145	    int        B;        // batch size (full-batch in the race ≈ 4191)
146	    float*     workspace; // grad partials + loss partials + reduced loss
147	    float*     loss_out;  // device float the kernel writes the mean loss into
148	};
149	
150	// ── The persistent megakernel (L3-REAL). gridDim.x = #SMs (one CTA/SM), 256
151	//    threads/CTA. The smem holds ONE DecSampleSmem (≈42 KB, < 48 KB static cap —
152	//    no dynamic-smem opt-in, so the occupancy≥1 guard with dynamicSMemBytes=0 in
153	//    the launcher is unchanged). ────────────────────────────────────────────────
154	// sizes/offsets are NOT host-passed: the per-tensor numel/offset live in the
155	// generated __constant__ tables kDecSizes/kDecOffsets (decoder_layout.cuh), so
156	// the reduce + optimizer phases read them directly. This also lets the host side
157	// (dispatch.cpp) avoid building any layout tensors.
158	template <OptId Opt>
159	__global__ void __launch_bounds__(SG_TUNED_MEGA_BLOCK)
160	fused_decoder_megakernel(PersistentContext ctx,
161	                         float* __restrict__ params,
162	                         DecoderTokenCtx tok,
163	                         float* __restrict__ grad,        // reduced grad [total]
164	                         float lr, int step, FusedOptState st) {
165	    __shared__ DecSampleSmem sm;
166	    GridBarrier bar = ctx.barrier();
167	    const int cta = blockIdx.x;
168	    const int nCTA = (int)ctx.n_ctas;
169	    const int64_t total = kDecTotalElems;
170	    float* my_partial = tok.workspace + (int64_t)cta * total;   // this CTA's dW
171	    float* loss_part = tok.workspace + (int64_t)nCTA * total;   // [nCTA]
172	
173	    // §3.4 register repartition (producer WG gives back, consumer WG claims).
174	    const int wg = threadIdx.x / 128;
175	    // warp-specialize prims live in sg::sm90::wgs (this file is sg::fused::sm90)
176	    if (wg == 0) ::sg::sm90::wgs::warpgroup_reg_dealloc<32>();
177	    else         ::sg::sm90::wgs::warpgroup_reg_alloc<200>();
178	
179	    // ── P0: zero this CTA's grad-partial slice + its loss slot. ───────────────
180	    for (int64_t i = threadIdx.x; i < total; i += blockDim.x) my_partial[i] = 0.0f;
181	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
182	    bar.sync();   // B0
183	
184	    // ── P1: batch-parallel fwd+bwd. Fixed contiguous slice [b0,b1) for this CTA.
185	    DecWeights w = dec_bind(params);
186	    DecGrad g = dec_bind_grad(my_partial);
187	    // Even split with remainder to the low CTAs (contiguous, deterministic).
188	    const int B = tok.B;
189	    const int base = B / nCTA, rem = B % nCTA;
190	    const int b0 = cta * base + (cta < rem ? cta : rem);
191	    const int cnt = base + (cta < rem ? 1 : 0);
192	    const int b1 = b0 + cnt;
193	    __shared__ int tok_s[dec::kSeq];   // this sample's token ids (broadcast)
194	    __shared__ int tgt_s;
195	    float nll_acc = 0.0f;              // fp32 slice accumulator (thread-0 holds it)
196	    for (int b = b0; b < b1; ++b) {
197	        if (threadIdx.x < dec::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * dec::kSeq + threadIdx.x];
198	        if (threadIdx.x == 0) tgt_s = tok.targets[b];
199	        __syncthreads();
200	        float nll = dec_forward_sample(w, tok_s, tgt_s, &sm);
201	        dec_backward_sample(w, g, tok_s, tgt_s, B, &sm);
202	        if (threadIdx.x == 0) nll_acc += nll;   // fixed-order fp32 sum within slice
203	        __syncthreads();   // sample boundary: all grad writes done before reuse
204	    }
205	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
206	    bar.sync();   // B1: all CTA partials + loss slots complete
207	
208	    // ── P2: deterministic cross-CTA reduce. Work-steal the param ELEMENT-RANGES
209	    //    (one task = one parameter tensor; sum its elements across CTAs in
210	    //    ascending CTA index). The summation ORDER (ascending cta) is fixed, so
211	    //    the result is deterministic regardless of which CTA grabs the task. ────
212	    {
213	        __shared__ int task_slot;
214	        TaskQueue q = ctx.queue();
215	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
216	             t = q.next_block(&task_slot)) {
217	            const int n = kDecSizes[t];
218	            const int64_t off = (int64_t)kDecOffsets[t];
219	            for (int i = threadIdx.x; i < n; i += blockDim.x) {
220	                float acc = 0.0f;
221	                // ascending CTA index → fixed fp32 summation order (deterministic).
222	                for (int c = 0; c < nCTA; ++c)
223	                    acc += tok.workspace[(int64_t)c * total + off + i];
224	                grad[off + i] = acc;
225	            }
226	        }
227	    }
228	    // Loss reduction (fp64 ordered) by CTA 0 only — the 1e-5 loss rel-tol is the
229	    // tightest gate; fp32 atomic-summing ~4191 terms can miss it.
230	    if (cta == 0 && threadIdx.x == 0) {
231	        double s = 0.0;
232	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
233	        float mean = (float)(s / (double)B);
234	        *tok.loss_out = mean;
235	    }
236	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue for P3
237	
238	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
239	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
240	    st.lr = lr;
241	    {
242	        __shared__ int task_slot;
243	        TaskQueue q = ctx.queue();
244	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
245	             t = q.next_block(&task_slot)) {
246	            const int n = kDecSizes[t];
247	            const int64_t off = (int64_t)kDecOffsets[t];
248	            const FusedOptState ts = rebase_state<Opt>(st, off);
249	            float* __restrict__ p = params + off;
250	            const float* __restrict__ gg = grad + off;
251	            for (int i = threadIdx.x; i < n; i += blockDim.x)
252	                apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
253	        }
254	    }
255	}
