257	// ── Host launcher — one persistent CTA per SM, 256 threads/CTA (2 warp-groups).
258	//    Mirrors launch_fused_megakernel's hang-freedom contract: occupancy≥1 or
259	//    refuse (the GridBarrier rendezvous of n_ctas CTAs can never complete if a
260	//    CTA can't be placed). Zeroes the barrier+task counters per launch. ─────────
261	template <OptId Opt>
262	cudaError_t launch_fused_decoder_megakernel(
263	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
264	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream) {
265	    int dev = 0;
266	    cudaError_t err = cudaGetDevice(&dev);
267	    if (err != cudaSuccess) return err;
268	    int n_sms = 0;
269	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
270	    if (err != cudaSuccess) return err;
271	
272	    int occ = 0;
273	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
274	        &occ, (const void*)&fused_decoder_megakernel<Opt>, SG_TUNED_MEGA_BLOCK,
275	        /*dynamicSMemBytes=*/0);
276	    if (err != cudaSuccess) return err;
277	    // Hang-freedom: at least one CTA per SM must be resident or the grid barrier
278	    // can never be satisfied. The L3-REAL kernel uses ≈42 KB static smem + a high
279	    // register count; if it cannot place one block/SM, REFUSE rather than hang.
280	    assert(occ >= 1 &&
281	           "fused_decoder_megakernel: 0 blocks/SM — GridBarrier would hang. The "
282	           "decoder smem (~42KB) + regs exceed one-block-per-SM occupancy; "
283	           "reduce footprint or fall back to the L1 per-op path.");
284	    if (occ < 1) return cudaErrorLaunchOutOfResources;
285	
286	    const unsigned launch_ctas = (unsigned)n_sms;
287	    ctx.n_ctas = launch_ctas;
288	
289	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
290	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
291	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
292	
293	    dim3 grid(launch_ctas), block(SG_TUNED_MEGA_BLOCK);
294	    fused_decoder_megakernel<Opt><<<grid, block, 0, stream>>>(
295	        ctx, params, tok, grad, lr, step, st);
296	    return cudaGetLastError();
297	}
298	
299	// ════════════════════════════════════════════════════════════════════════════
300	//  WGMMA CELL DRIVER (DESIGN-TC-PIPELINE.md Fork B, R2.3). Compiled only under
301	//  the wgmma token; the scalar path above is untouched.
302	// ════════════════════════════════════════════════════════════════════════════
303	#if (SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA)
304	
305	// TC megakernel threads: 256 (the engine's producer+consumer warpgroup layout;
306	// wgmma is warpgroup-scoped on threads 0..127). We do NOT apply the scalar
307	// path's asymmetric setmaxnreg (dealloc<32> on WG0) — that would STARVE the MMA
308	// warpgroup (WG0 issues the wgmma; a 128-wide accumulator needs 64 fp32 regs/
309	// thread). The validated selftest ran no split; we match it.
310	#define SG_TC_MEGA_BLOCK 256
311	
312	// ── smem arena for the unpipelined engine: one A(64×16) + one B(N×16) bf16 tile
313	//    + the 256-float reduction slot. 16B-aligned. N = SG_TUNED_TILE_N. The 9 dW
314	//    specs live here too (identical for all threads → shared, not per-thread
315	//    stack: keeps the launch's local-memory reservation small so the persistent
316	//    kernel places on a memory-tight GPU). ──
317	struct DecTcSmem {
318	    // kDecTcStages A(64×16) + kDecTcStages B(N×16) bf16 tiles — the GEMM K-loop
319	    // double-buffer ring (slot s at sA + s*64*16 / sB + s*N*16). At S=2 + N=128
320	    // the ring is 2·(2KB+4KB)=12KB; DecTcSmem total ~13.5KB ≪ the 48KB static cap.
321	    __nv_bfloat16 sA[dectc::kDecTcStages * 64 * 16];
322	    __nv_bfloat16 sB[dectc::kDecTcStages * SG_TUNED_TILE_N * 16];
323	    float red[256];
324	    dectc::DecDwSpec spec[9];
325	};
326	
327	// ── TC workspace layout (carved from tok.workspace; the host sizes it for the
328	//    TC path — see dec_tc_workspace_floats). Regions (float units):
329	//      [0 .. acts_f)                      : DecActs bf16 region (reinterpreted)
330	//      [acts_f .. acts_f + nCTA*scratch)  : per-CTA tile scratch (f32)
331	//      [.. + nCTA*kLnVecElems)            : per-CTA LN-vec partials (f32)
332	//      [.. + nCTA)                        : per-CTA loss slots (f32)
333	//      [.. + 1)                           : reduced scalar loss (host reads it)
334	//    acts_f = ceil(acts_bf16 / 2). ──
335	__host__ __device__ __forceinline__ int64_t dec_tc_acts_floats(int T, int B) {
336	    // mirror dectc::dec_acts_bind's running offset (bf16 elems) → floats.
337	    const int64_t d = dec::kD, dff = dec::kDff, V = dec::kVocab, L = dec::kLayers;
338	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
339	    int64_t bf = 0;
340	    for (int li = 0; li < L; ++li) bf += Td + Td + Td + Tff + T3d + Td + Tff + Td;
341	    bf += (int64_t)B * d + (int64_t)B * V + Td;     // X_hn + dY_logits + dh0
342	    return (bf + 1) / 2;
343	}
344	// dW split-K partial floats (0 when G==1 → no extra scratch, single-CTA path).
345	__host__ __device__ __forceinline__ int64_t dec_tc_dw_part_floats() {
346	    return (dectc::kDecDwSplitK > 1) ? dectc::dec_dw_part_floats(dectc::kDecDwSplitK) : 0;
347	}
348	// STAGED-optimizer cross-CTA reduction scratch (Prodigy d-estimate). The Prodigy
349	// stage publishes per-CTA (r,s) slots (2*nCTA) + a reduced-d slot (1) — an owner-
350	// computes tree (opt_stages_precompute.cuh), NO float atomic. Sized for the
351	// LARGEST nCTA (one CTA/SM = #SMs); tiny (≤ 2*132+1 ≈ 1 KB) and carved
352	// UNCONDITIONALLY so the opt-agnostic host launcher (dec_tc_launcher_scratch)
353	// allocates one workspace that fits every OptId. Unused by AdamW/Lion/… (their
354	// P3 never touches this region), so adding it leaves those cells byte-identical.
355	__host__ __device__ __forceinline__ int64_t dec_tc_opt_reduce_floats(int nCTA) {
356	    return (int64_t)2 * nCTA + 1;            // [r slots | s slots | reduced d]
357	}
358	// ── Muon (STAGED grid-cooperative Newton-Schulz) per-matrix scratch. IDENTICAL in
359	//    shape to the vit twin (vit_tc_muon_floats): the NS chain runs ONE 2D weight at
360	//    a time over all CTAs; the scratch holds X/A/AX/AAX/orth for the LARGEST 2D weight
361	//    + the per-CTA Frobenius-norm partials + inv_norm. The momentum buffer (muon_buf)
362	//    is NOT here — it PERSISTS across steps as optimizer state, bound to the m slice
363	//    (st.exp_avg). Largest decoder 2D weight: ff.0/ff.2 = 512×128 = 65536 numel; largest
364	//    rows = 512 ⇒ A = 512×512 (dectc::kDecMuonMaxNumel/kDecMuonMaxRows). Carved
365	//    UNCONDITIONALLY (≈ 4·65536 + 512² + nCTA + 1 floats ≈ 2 MB) so the opt-agnostic
366	//    launcher (dec_tc_launcher_scratch) fits every OptId; unused by every non-Muon cell
367	//    (its P2.7/P3-2D branches are if-constexpr'd out → byte-identical). ──
368	__host__ __device__ __forceinline__ int64_t dec_tc_muon_floats(int nCTA) {
369	    // X + AX + AAX + orth (each maxNumel) + A (maxRows²) + nrm_partials(nCTA) + inv_norm(1)
370	    return (int64_t)4 * dectc::kDecMuonMaxNumel
371	         + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows
372	         + nCTA + 1;
373	}
374	__host__ __device__ __forceinline__ int64_t dec_tc_workspace_floats(int T, int B, int nCTA) {
375	    return dec_tc_acts_floats(T, B)
376	         + (int64_t)nCTA * dectc::dec_tile_scratch_total_f32()
377	         + (int64_t)nCTA * dectc::kLnVecElems
378	         + nCTA + 1
379	         + dec_tc_dw_part_floats()            // split-K dW partials (G>1)
380	         + dec_tc_opt_reduce_floats(nCTA)     // STAGED-opt (Prodigy) reduce slots
381	         + dec_tc_muon_floats(nCTA);          // STAGED-opt (Muon) NS per-matrix scratch
382	}
383	
384	template <OptId Opt>
385	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
386	fused_decoder_megakernel_tc(PersistentContext ctx,
387	                            float* __restrict__ params,
388	                            DecoderTokenCtx tok,
389	                            float* __restrict__ grad,
390	                            float lr, int step, FusedOptState st) {
391	    __shared__ DecTcSmem sm;
392	    GridBarrier bar = ctx.barrier();
393	    const int cta = blockIdx.x;
394	    const int nCTA = (int)ctx.n_ctas;
395	    const int B = tok.B;
396	    const int T = B * dec::kSeq;
397	
398	    // Workspace partition.
399	    float* ws = tok.workspace;
400	    const int64_t acts_f = dec_tc_acts_floats(T, B);
401	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
402	    float* scratch_base = ws + acts_f;
403	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
404	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
405	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
406	    float* loss_out   = loss_part + nCTA;
407	    // Split-K dW partials (G>1): the (gt,kc) 64×N partial tiles, carved AFTER the
408	    // loss slot (matches dec_tc_workspace_floats's term order). G==1 → dw_part unused.
409	    float* dw_part    = loss_out + 1;
410	    const int kDwG    = dectc::kDecDwSplitK;
411	    // STAGED-opt cross-CTA reduce slots (Prodigy d), carved AFTER the dW partials
412	    // (matches dec_tc_workspace_floats's term order). Unused unless Opt==Prodigy.
413	    float* opt_reduce = dw_part + dec_tc_dw_part_floats();
414	    // Muon NS per-matrix scratch, carved AFTER the Prodigy reduce slots (matches
415	    // dec_tc_workspace_floats's term order — carving it LAST keeps every prior
416	    // region's offset unchanged, so the 5 already-green cells are byte-identical).
417	    // Unused unless Opt==Muon. Layout (mirrors the vit twin):
418	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kDecMuonMaxNumel)
419	    //   [muon_A (kDecMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
420	    float* muon_base = opt_reduce + dec_tc_opt_reduce_floats(nCTA);
421	
422	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
423	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
424	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
425	
426	    DecWeights w = dec_bind(params);
427	
428	    // ── P0: zero this CTA's LN-vec partials + loss slot (dW/embed grads are
429	    //    written-once → no pre-zero). ──
430	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
431	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
432	    bar.sync();   // B0
433	
434	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
435	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
436	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
437	    const int nrows_tile = dectc::kTileM;
438	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
439	    float nll_acc = 0.0f;
440	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
441	        const int g0 = ti * nrows_tile;
442	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
443	        float nll = dectc::dectc_forward_tile(w, g0, nrows, acts, sc, tok.tokens, tok.targets,
444	                                              sm.sA, sm.sB, sm.red);
445	        dectc::dectc_backward_tile(w, g0, nrows, B, acts, sc, tok.targets,
446	                                   my_lnvec, sc.work2, sm.sA, sm.sB, sm.red);
447	        if (threadIdx.x == 0) nll_acc += nll;
448	        __syncthreads();
449	    }
450	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
451	    bar.sync();   // B1: all acts (X + dY) + LN-vec partials complete
452	
453	    // ── P2: assemble all 30 grads into `grad`. dW output-stationary (gt %
454	    //    nCTA), biases, embedding owner-scan, LN-vec reduce. No partials. The 9
455	    //    dW specs are built into SHARED smem (thread 0; identical for all) so the
456	    //    9-spec array is NOT on every thread's stack (shrinks the launch's local
457	    //    reservation — the persistent kernel must place on a memory-tight GPU). ──
458	    if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
459	    __syncthreads();
460	    dectc::DecDwSpec* spec = sm.spec;
461	    const int n_dw = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
462	    if (kDwG > 1) {
463	        // SPLIT-K (multi-CTA tiling): fan (n_dw·G) (tile,chunk) partials over the
464	        // grid so the ~62% idle SMs do work; deterministic ascending-chunk reduce.
465	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {
466	            const int gt = item / kDwG, kc = item % kDwG;
467	            dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
468	        }
469	        bar.sync();   // all (gt,kc) partials complete before the reduce reads them
470	        dectc::dectc_dw_reduce_splitk<SG_TUNED_TILE_N>(spec, n_dw, kDwG, dw_part, grad, cta, nCTA);
471	    } else {
472	        for (int gt = cta; gt < n_dw; gt += nCTA)
473	            dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
474	    }
475	    dectc::dectc_dw_biases(spec, grad);
476	    dectc::dectc_embed_owner_scan(acts, tok.tokens, T, grad, cta, nCTA);
477	    dectc::dectc_lnvec_reduce(lnvec_base, grad, nCTA, cta);
478	    // Loss reduce (fp64) by CTA 0.
479	    if (cta == 0 && threadIdx.x == 0) {
480	        double s = 0.0;
481	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
482	        *tok.loss_out = (float)(s / (double)B);
483	    }
484	    (void)loss_out;
485	    bar.sync_reset(ctx.g_next_task);   // B2: reduced grad ready; reset queue
486	
487	    // ── P2.5 (GrokAdamW ONLY): GLOBAL grad-norm clip coefficient. Eager
488	    //    grokadamw clips the WHOLE grad set to grad_clip via a GLOBAL L2 norm
489	    //    (clip_grad_norms_device_side → total_norm = sqrt(Σ_i ‖g_i‖²),
490	    //    clip_coef = grad_clip/(total_norm+1e-6) when total_norm>grad_clip,
491	    //    else 1) BEFORE the apply. We replicate it on the REDUCED grad with a
492	    //    deterministic ascending reduction (no float atomics): each CTA sums a
493	    //    contiguous element-range into a per-CTA partial slot, CTA0 sums the
494	    //    partials in ascending CTA order → total_norm → clip_coef, broadcast via
495	    //    a workspace slot. The grad buffer is NOT mutated (the return_grad oracle
496	    //    + the eager-side clip must both see the unclipped reduced grad); the
497	    //    coefficient is applied per-element inside apply_optimizer<GrokAdamW>.
498	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
499	    if constexpr (Opt == OptId::GrokAdamW) {
500	        // Reuse the (now-consumed) loss workspace: loss_part[nCTA] holds per-CTA
501	        // partial sum-of-squares; loss_out (1 float) broadcasts clip_coef. The
502	        // reduced loss is already in *tok.loss_out (state), so this is free scratch.
503	        float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
504	        float* coef_bc = loss_out;           // [1] broadcast clip_coef
505	        // Per-CTA contiguous element range over `grad` (the reduced grad, [total]).
506	        const int64_t total = kDecTotalElems;
507	        const int64_t base = total / nCTA, rem = total % nCTA;
508	        const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
509	        const int64_t ecnt = base + (cta < rem ? 1 : 0);
510	        // Thread-local partial → block reduce (fixed tree) → thread0 writes the slot.
511	        float tsum = 0.0f;
512	        for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
513	            const float gv = grad[e0 + i];
514	            tsum += gv * gv;
515	        }
516	        // Block reduction via the smem the TC GEMM already owns (sm.red, fp32).
517	        float* red = sm.red;
518	        red[threadIdx.x] = tsum;
519	        __syncthreads();
520	        for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
521	            if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
522	            __syncthreads();
523	        }
524	        if (threadIdx.x == 0) sq_part[cta] = red[0];
525	        bar.sync();   // B2.5a: all per-CTA sum-of-squares partials complete
526	        // CTA0 ascending-order reduce → total_norm → clip_coef (deterministic).
527	        if (cta == 0 && threadIdx.x == 0) {
528	            double ss = 0.0;
529	            for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
530	            const float total_norm = sqrtf((float)ss);
531	            float coef = 1.0f;
532	            if (st.grad_clip > 0.0f && total_norm > st.grad_clip)
533	                coef = st.grad_clip / (total_norm + 1e-6f);
534	            *coef_bc = coef;
535	        }
536	        bar.sync();   // B2.5b: clip_coef broadcast slot ready for all CTAs
537	        st.clip_coef = *coef_bc;   // every CTA reads the single global coefficient
538	    }
539	
540	    // ── P2.6 (PRODIGY ONLY): STAGED cross-ALL-tensors d-estimate. The apply tail
541	    //    (apply_optimizer<Prodigy>) reads st.d_factor (the effective LR scale d),
542	    //    a GLOBAL reduction over EVERY element of EVERY tensor. We compute it here,
543	    //    BYTE-FAITHFUL to the live eager multi-tensor path (prodigy_sm90.cuh:465-
544	    //    544, the order prodigy.py → _ops.prodigy_fused_step actually executes):
545	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state
546	    //                slot would give d_prev=0 ⇒ d=0 ⇒ frozen params; eager inits
547	    //                _d_lr=d0=1e-6, so seed it here, the grokfast-style step-1 fix)
548	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
549	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
550	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
551	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
552	    //
553	    //    DETERMINISM — FIXED-PARTITION reduction (mirrors the A/A/A-CLEAN GrokAdamW
554	    //    P2.5 grad-norm reduce above), NOT the work-steal task-queue drain. WHY THIS
555	    //    SHAPE: the previous form drained the global TaskQueue (q.next_block →
556	    //    atomicAdd(g_next_task)) inside phaseA and reset that SAME counter in a
557	    //    sync_RESET barrier (B2.6a). The work-steal claim order is timing-dependent,
558	    //    so each CTA's (r,s) slot holds a potentially DIFFERENT tensor subset run-to-
559	    //    run; because fp32 add is non-associative, the per-CTA partials then regroup
560	    //    the same values differently and the owner's d can differ at ULP level from
561	    //    step>=2 (a COMPONENT_CONTRACT deterministic-reduction violation — even where
562	    //    it happens to be empirically bit-exact on a given GPU/workload, it is not
563	    //    deterministic BY CONSTRUCTION). GrokAdamW's P2.5 reduces a FIXED contiguous
564	    //    element range per CTA with a plain sync() and is A/A/A-CLEAN; prodigy now
565	    //    uses the IDENTICAL shape — deterministic by construction, independent of CTA
566	    //    timing. Each CTA owns [e0,e0+ecnt) of the FLAT [0,total) arrays —
567	    //    params/param_init/grad are parallel flat blobs, so a contiguous flat range
568	    //    sum == the cross-all-TENSORS sum (tensor boundaries are irrelevant to a
569	    //    global Σ). The per-element contribution still CALLS the canonical
570	    //    prodigy_partials_step (prodigy.h:28-53, single-source). NO float atomic;
571	    //    per-CTA (r,s) slot publish → ONE plain grid barrier → CTA0 owner-sums
572	    //    ascending → EMA-decay/update_d → broadcast → ONE plain grid barrier.
573	    //    g_next_task is UNTOUCHED here (B2 already reset it to 0), so P3's queue
574	    //    drain runs unchanged — no sync_reset needed in P2.6.
575	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
576	    if constexpr (Opt == OptId::Prodigy) {
577	        // Per-CTA (r,s) slots in opt_reduce ([r slots | s slots]) + the reduced-d
578	        // broadcast slot. d_prev: persisted d_lr (slot 2), or d0 cold-start at step 1.
579	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
580	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
581	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
582	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
583	        // FIXED contiguous element range over the flat [0,total_p) arrays (same split
584	        // as GrokAdamW P2.5: even base + remainder to the low CTAs → deterministic).
585	        const int64_t total_p = kDecTotalElems;
586	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
587	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
588	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
589	        float r_acc = 0.0f, s_acc = 0.0f;
590	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
591	            // Canonical per-element partials (prodigy.h:28-53): r carries d²·<g,p0−p>,
592	            // s carries d²·|g| (the L1-norm denominator). params/param_init/grad are
593	            // flat blobs → index pe0+i is the same element in all three.
594	            algo::prodigy_partials_step(params, st.param_init, grad,
595	                                        d_prev, pe0 + i, r_acc, s_acc);
596	        }
597	        // Deterministic in-CTA two-value reduction (fixed thread count) → thread0
598	        // publishes this CTA's (r,s) slot. No atomic.
599	        float r_block, s_block;
600	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
601	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
602	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
603	        // Owner block (CTA0 thread0): ascending owner-sum + EMA decay + accumulate +
604	        // d_coef + update_d, byte-matching launch_multi_tensor_prodigy_fused_reduce_step.
605	        if (cta == 0 && threadIdx.x == 0) {
606	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
607	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
608	            // Decay persisted scalars by beta3, then add this step's reduction.
609	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
610	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
611	            // d = max(d_prev, d_coef·r_ema/|s_ema|). prodigy_update_d does
612	            // max(d_prev, r/|s|) verbatim, so fold d_coef into the numerator copy
613	            // (persisted r_ema stays UNSCALED — returned/persisted, eager parity).
614	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
615	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
616	            st.prodigy_persist[1] = s_ema;
617	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
618	            d_bc[0]               = d_new;          // broadcast to all CTAs
619	        }
620	        bar.sync();   // B2.6b: d visible to every CTA before the apply
621	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
622	    }
623	
624	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
625	    //    2D weights (INTEGRATION-OPTSTAGES §3). IDENTICAL to the vit twin
626	    //    (fused_vit_megakernel.cuh P2.7) — same shared opt_stages_precompute.cuh
627	    //    helpers, same barrier sequence — only the per-model 2D table (dectc::
628	    //    kDecMuon2D, 11 matrices including tok[99,128]/pos[4,128]) and offset array
629	    //    (kDecOffsets) differ. For EACH 2D matrix all CTAs cooperate: buf=μ·buf+g
630	    //    (buf is the PERSISTENT m-slice — momentum state, NOT transient), ‖buf‖_F via
631	    //    per-CTA partials → inv_norm, X=buf·inv_norm, then ns_steps × { A=XXᵀ → AX=A·X
632	    //    → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap }, then the canonical muon_update_step
633	    //    apply (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (biases, LN γ/β)
634	    //    take the AdamW aux tail in P3. The elementwise bodies CALL muon.h
635	    //    (muon_momentum_normalize_step via the phaseA buf body, muon_ns_combine_step,
636	    //    muon_update_step); the matmuls are the cited new device code (the eager path
637	    //    delegates to torch::mm/cuBLAS). Guarded so every other opt is byte-identical
638	    //    (no extra barriers / work).
639	    if constexpr (Opt == OptId::Muon) {
640	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
641	        PrecomputeWorkspace pw{};
642	        pw.muon_X            = muon_base;
643	        pw.muon_AX           = pw.muon_X   + dectc::kDecMuonMaxNumel;
644	        pw.muon_AAX          = pw.muon_AX  + dectc::kDecMuonMaxNumel;
645	        pw.muon_orth         = pw.muon_AAX + dectc::kDecMuonMaxNumel;
646	        pw.muon_A            = pw.muon_orth + dectc::kDecMuonMaxNumel;
647	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows;
648	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
649	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
650	        const int   ns_steps = 5;                 // bindings.cpp default
651	        for (int mi = 0; mi < dectc::kDecNumMuon2D; ++mi) {
652	            const dectc::DecMuon2D M = dectc::kDecMuon2D[mi];
653	            const int rows = M.rows, cols = M.cols;
654	            const int64_t numel = (int64_t)rows * cols;
655	            const int64_t off   = (int64_t)kDecOffsets[M.tidx];
656	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
657	            pw.muon_buf = st.exp_avg + off;
658	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
659	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
660	            bar.sync();
661	            muon_norm_reduce_phaseB(ctx, pw);
662	            bar.sync();
663	            muon_scale_X(numel, pw);
664	            bar.sync();
665	            // NS iterations. After each combine, orth holds the new iterate; swap so
666	            // the next iteration reads it as X. ns_steps swaps → final result is in
667	            // muon_X (the last combine wrote muon_orth, then we swapped → muon_X).
668	            for (int s = 0; s < ns_steps; ++s) {
669	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
670	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
671	                bar.sync();
672	                // AX = A X   (M=rows,N=cols,K=rows).
673	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
674	                bar.sync();
675	                // AAX = A (AX) (M=rows,N=cols,K=rows).
676	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
677	                bar.sync();
678	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
679	                bar.sync();
680	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
681	            }
682	            // Apply Muon: p = decay_factor·p + neg_lr_scale·orth  (muon.h:63-73).
683	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
684	            const float neg_lr_scale = -lr * scale;
685	            const float decay_factor = 1.0f - lr * st.wd;
686	            float* __restrict__ p = params + off;
687	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
688	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
689	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
690	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
691	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
692	        }
693	    }
694	
695	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
696	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
697	    st.lr = lr;
698	    {
699	        __shared__ int task_slot;
700	        TaskQueue q = ctx.queue();
701	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
702	             t = q.next_block(&task_slot)) {
703	            const int n = kDecSizes[t];
704	            const int64_t off = (int64_t)kDecOffsets[t];
705	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
706	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
707	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
708	            if constexpr (Opt == OptId::Muon) {
709	                if (dectc::dec_is_muon_2d(t)) continue;
710	            }
711	            FusedOptState ts = rebase_state<Opt>(st, off);
712	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
713	            //     t == the tensor's flat named_parameters() layer index (the
714	            //     work-steal task id maps 1:1 to kDecOffsets order == the eager
715	            //     enumeration order, so t IS the eager layer index). bc1 must be
716	            //     rebased TOO (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager
717	            //     (~9.6× on the deepest layer); bc2 stays global (β2 not layer-wise).
718	            if constexpr (Opt == OptId::GrokAdamW) {
719	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
720	                ts.beta1 = b1;
721	                ts.bc1   = 1.0f - powf(b1, (float)step);
722	            }
723	            float* __restrict__ p = params + off;
724	            const float* __restrict__ gg = grad + off;
725	            if constexpr (Opt == OptId::Muon) {
726	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:99-125 routes
727	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
728	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
729	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
730	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
731	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
732	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
733	                // bc1/bc2 are device-computed from aux_beta^step (kept out of the mirror
734	                // to shrink the host ABI; fp32 powf, tol 2e-3 ample). apply_optimizer<Muon>
735	                // would deref st.orth (NS dir, only valid for 2D), so route directly to
736	                // adamw_step with the aux hyperparameters — IDENTICAL to the vit twin.
737	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
738	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
739	                for (int i = threadIdx.x; i < n; i += blockDim.x)
740	                    algo::adamw_step<float, float>(
741	                        p, ts.exp_avg, ts.exp_avg_sq, gg,
742	                        st.aux_lr, st.aux_beta1, st.aux_beta2, ts.eps, ts.wd,
743	                        a_bc1, a_bc2, (int64_t)i);
744	            } else {
745	                for (int i = threadIdx.x; i < n; i += blockDim.x)
746	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
747	            }
748	        }
749	    }
750	}
751	
752	// ncta_cap (default 0): if >0, launch min(n_sms, ncta_cap) CTAs instead of one
753	// per SM. The grid barrier rendezvous is over the LAUNCHED count (ctx.n_ctas),
754	// so any cap is hang-safe as long as the workspace + dW-tile/embedding ownership
755	// use the SAME nCTA (they read ctx.n_ctas). The shipped path passes 0 (full
756	// saturation); a memory-constrained TEST passes a small cap so the per-CTA
757	// scratch fits (the scratch is nCTA×slab). Determinism is preserved per fixed
758	// nCTA (the dW/embedding owner maps are functions of nCTA).
759	template <OptId Opt>
760	cudaError_t launch_fused_decoder_megakernel_tc(
761	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
762	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
763	        int ncta_cap = 0) {
764	    int dev = 0;
765	    cudaError_t err = cudaGetDevice(&dev);
766	    if (err != cudaSuccess) return err;
767	    int n_sms = 0;
768	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
769	    if (err != cudaSuccess) return err;
770	
771	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem
772	    // (0 here — DecTcSmem is static). If the static smem + 200-reg consumer
773	    // can't place one block/SM, REFUSE (the grid barrier would hang).
774	    int occ = 0;
775	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
776	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
777	        /*dynamicSMemBytes=*/0);
778	    if (err != cudaSuccess) return err;
779	    if (occ < 1) return cudaErrorLaunchOutOfResources;
780	
781	    unsigned launch_ctas = (unsigned)n_sms;
782	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
783	    ctx.n_ctas = launch_ctas;
784	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms,
785	    // AND it guarantees full token tiles for the projections). NO G-divisibility
786	    // guard: the split-K dW uses a FLOOR-BALANCED K-partition (dectc_dw_run_tile_
787	    // splitk) that sums to KS exactly for any KS≥G, so it works at the production
788	    // truncated B (e.g. 4176, where head KS=B/16=261 is NOT divisible by G=4).
789	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
790	
791	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
792	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
793	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
794	
795	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
796	    fused_decoder_megakernel_tc<Opt><<<grid, block, 0, stream>>>(
797	        ctx, params, tok, grad, lr, step, st);
798	    return cudaGetLastError();
799	}
