136	void launch_sg11_mu_metanet(
137	    torch::Tensor mu, torch::Tensor grad, torch::Tensor sharpness,
138	    torch::Tensor smart_grad, float alpha,
139	    torch::Tensor W1, torch::Tensor b1, torch::Tensor W2, torch::Tensor b2,
140	    float rescale, int hidden_dim
141	) {
142	    const int64_t N = mu.numel();
143	    if (N == 0) return;
144	    auto stream = at::cuda::getCurrentCUDAStream().stream();
145	    const int block = SG_TUNED_BLOCK_SIZE;
146	    const int grid = static_cast<int>(
147	        std::min<int64_t>(65535, (N + block - 1) / block));
148	    float b2_val = b2.item<float>();
149	
150	    AT_DISPATCH_FLOATING_TYPES_AND2(
151	        at::ScalarType::Half, at::ScalarType::BFloat16,
152	        grad.scalar_type(), "sg11_mu_metanet", [&] {
153	            sg11_mu_metanet_kernel<scalar_t><<<grid, block, 0, stream>>>(
154	                mu.data_ptr<float>(),
155	                grad.data_ptr<scalar_t>(),
156	                sharpness.data_ptr<float>(),
157	                smart_grad.data_ptr<float>(), alpha,
158	                W1.data_ptr<float>(), b1.data_ptr<float>(),
159	                W2.data_ptr<float>(), b2_val, rescale, N);
160	            SG_LAUNCH_CHECK(stream);
161	        });
162	}
