164	// Adam + decoupled WD on smart_grad, with optional lamb-scaled mu blending.
165	__global__ void sg11_adam_decay_kernel(
166	    float* param, float* exp_avg, float* exp_avg_sq,
167	    const float* smart_grad, const float* mu,
168	    float lamb_eff, float beta1, float beta2, float lr,
169	    float wd_eff, float eps, float bc1, float bc2, int64_t N
170	) {
171	    const int64_t stride = prim::grid_stride();
172	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
173	        // g_eff = smart_grad + lamb_eff*mu blending; the bias-corrected Adam +
174	        // decoupled-WD math lives once in algorithms/supergrok11.h.
175	        const float g_eff = ::grokking::sm90::sg_sanitize_grad(smart_grad[i]) +
176	                            lamb_eff * mu[i];
177	        sg11_adam_tail(param, exp_avg, exp_avg_sq, g_eff,
178	                       lr, beta1, beta2, eps, wd_eff, bc1, bc2, i);
179	    }
180	}
