274	// Cosine gate: cos_sim(smart_grad, mu) clamped to [0,1].
275	float compute_cosine_gate_fused(
276	    torch::Tensor smart_grad, torch::Tensor mu, float gate_temp
277	) {
278	    auto sg_f = smart_grad.to(torch::kFloat32).flatten();
279	    auto mu_f = mu.to(torch::kFloat32).flatten();
280	    float num = (sg_f * mu_f).sum().item<float>();
281	    float den_g = (sg_f * sg_f).sum().item<float>();
282	    float den_m = (mu_f * mu_f).sum().item<float>();
283	    float denom = sqrtf(den_g * den_m + 1e-12f);
284	    float gate = (denom > 0.0f) ? (num / denom) : 0.0f;
285	    return fminf(fmaxf(gate, 0.0f), 1.0f);
286	}
